// React ka work loop (simplified)
function workLoopConcurrent() {
  while (workInProgress !== null && !shouldYield()) {
    workInProgress = performUnitOfWork(workInProgress);
  }
}

function shouldYield() {
  return getCurrentTime() >= deadline;   // ~5ms ka slice
}

// ek fiber pe kaam -- neeche jao, phir wapas upar
function performUnitOfWork(fiber) {
  const next = beginWork(fiber);         // "neeche jaate hue" -- render
  if (next) return next;                 // child mila -> uspe jao
  let node = fiber;
  while (node) {
    completeWork(node);                  // "wapas aate hue" -- DOM banao
    if (node.sibling) return node.sibling;
    node = node.return;                  // parent pe chadho
  }
  return null;                           // tree khatam
}

// sync mode ka loop -- yahan shouldYield NAHI hai, isliye block karta hai
function workLoopSync() {
  while (workInProgress !== null) workInProgress = performUnitOfWork(workInProgress);
}

