// simplified -- React ke andar kya hota hai
function updateState() {
  const hook = currentHook;               // order se mila
  let state = hook.baseState;
  let update = hook.queue.first;
  while (update) {                        // queue ke saare updates apply
    state = typeof update.action === 'function'
      ? update.action(state)              // functional -> LATEST state milta hai
      : update.action;                    // direct value
    update = update.next;
  }
  hook.memoizedState = state;
  return [state, hook.queue.dispatch];
}

