type State =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ok'; data: User }
  | { status: 'err'; msg: string };

type Action =
  | { type: 'FETCH' } | { type: 'OK'; data: User }
  | { type: 'ERR'; msg: string } | { type: 'RESET' };

function reducer(s: State, a: Action): State {
  switch (a.type) {
    case 'FETCH': return { status: 'loading' };
    case 'OK':    return { status: 'ok', data: a.data };
    case 'ERR':   return { status: 'err', msg: a.msg };
    case 'RESET': return { status: 'idle' };
  }
}

function User() {
  const [s, dispatch] = useReducer(reducer, { status: 'idle' });
  // impossible state ban hi nahi sakta -- loading + error saath mein nahi ho sakte
  useEffect(() => {
    dispatch({ type: 'FETCH' });
    load().then(d => dispatch({ type:'OK', data:d }))
          .catch(e => dispatch({ type:'ERR', msg:e.message }));
  }, []);
  if (s.status === 'loading') return <Spinner />;
  if (s.status === 'err')     return <p>{s.msg}</p>;   // TS jaanta hai msg hai
  return s.status === 'ok' ? <p>{s.data.name}</p> : null;
}

