const userSlice = createSlice({
  name: 'user',
  initialState: { data: null as User|null, loading: false, error: null as string|null },
  reducers: {
    logout(state) { state.data = null; },            // Immer -- mutate likh sakte ho
    rename(state, a: PayloadAction<string>) {
      state.data!.name = a.payload;                  // nested bhi seedha
    },
  },
  extraReducers: b => {
    b.addCase(fetchUser.pending,   s => { s.loading = true; s.error = null; })
     .addCase(fetchUser.fulfilled, (s, a) => { s.loading = false; s.data = a.payload; })
     .addCase(fetchUser.rejected,  (s, a) => { s.loading = false; s.error = a.error.message!; });
  },
});

