const TabsCtx = createContext<{active: string; set: (s:string)=>void} | null>(null);
const useTabs = () => {
  const c = useContext(TabsCtx);
  if (!c) throw new Error('Tabs.* ko <Tabs> ke andar use karo');
  return c;
};

function Tabs({ defaultValue, children }: PropsWithChildren<{defaultValue:string}>) {
  const [active, set] = useState(defaultValue);
  const v = useMemo(() => ({ active, set }), [active]);
  return <TabsCtx.Provider value={v}>{children}</TabsCtx.Provider>;
}

Tabs.List = ({ children }: PropsWithChildren) =>
  <div role="tablist">{children}</div>;

Tabs.Tab = ({ value, children }: PropsWithChildren<{value:string}>) => {
  const { active, set } = useTabs();
  return <button role="tab" aria-selected={active===value}
                 onClick={() => set(value)}>{children}</button>;
};

Tabs.Panel = ({ value, children }: PropsWithChildren<{value:string}>) => {
  const { active } = useTabs();
  return active === value ? <div role="tabpanel">{children}</div> : null;
};

