import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';

const Schema = z.object({
  email: z.string().email('Sahi email daalo'),
  password: z.string().min(8, '8 character chahiye'),
  confirm: z.string(),
}).refine(d => d.password === d.confirm, {
  message: 'Password match nahi kar rahe', path: ['confirm'],
});
type FormData = z.infer<typeof Schema>;      // type FREE mein mil gaya

function Signup() {
  const { register, handleSubmit, formState:{ errors, isSubmitting } } =
    useForm<FormData>({ resolver: zodResolver(Schema) });

  return (
    <form onSubmit={handleSubmit(async d => { await api.signup(d); })}>
      <input {...register('email')} aria-invalid={!!errors.email} />
      {errors.email && <span role="alert">{errors.email.message}</span>}

      <input type="password" {...register('password')} />
      {errors.password && <span role="alert">{errors.password.message}</span>}

      <button disabled={isSubmitting}>{isSubmitting ? 'Ruko...' : 'Signup'}</button>
    </form>
  );
}

